255	    @Override
256	    @Transactional
257	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
258	        rejectWhenDailyLimitReached(owner);
259	        rejectWhenCityAtCapacity(owner);
260	        List<Owner> householdMembers = assignHousehold(owner, sharesHousehold);
261	        rejectWhenDuplicateIdentity(owner);
262	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
263	        if (owner.getCustomerCode() == null) {
264	            owner.setCustomerCode(nextCustomerCode(owner));
265	        }
266	        if (owner.getNamesakeCount() == null) {
267	            owner.setNamesakeCount(countNamesakes(owner));
268	        }
269	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
270	        ownerRepository.save(owner);
271	    }
