273	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
274	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
275	
276	    /**
277	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
278	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
279	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
280	     * today by the controller, determines which day is counted — the same accumulation path as the
281	     * daily-limit rule.
282	     */
283	    private boolean exceedsBulkSignupThreshold(Owner owner) {
284	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
285	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
286	    }
287	
288	    /**
289	     * Count the existing owners that already share this owner's first name and last name,
290	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
291	     * before the owner is persisted, so it reflects the owners present at creation time.
292	     */
293	    private int countNamesakes(Owner owner) {
294	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
295	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
296	        return (int) ownerRepository.findAll().stream()
297	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
298	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
299	            .count();
300	    }
301	
302	    /**
303	     * Reconcile the owner's household and return its existing members. Owners are in the same
304	     * household when their last name and address match (compared case-insensitively with collapsed
305	     * whitespace). When another owner already lives there and {@code sharesHousehold} is set, the
306	     * new owner and every existing member are given the same stable shared {@code householdId} so
307	     * they form one household; without the opt-in the owner is treated as living alone (no shared
308	     * identifier). Duplicate detection no longer happens here: it is consolidated into the derived
309	     * {@code identityKey} (see {@link #rejectWhenDuplicateIdentity(Owner)}). The returned list is the
310	     * existing members that make up this owner's household (empty when the owner lives alone), so
311	     * callers can derive the household size after this create.
312	     */
313	    private List<Owner> assignHousehold(Owner owner, boolean sharesHousehold) {
314	        if (!sharesHousehold) {
315	            return List.of();
316	        }
317	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
318	        String address = AddressNormalizer.canonical(owner.getAddress());
319	        List<Owner> householdMembers = ownerRepository.findAll().stream()
320	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
321	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
322	            .toList();
323	        if (householdMembers.isEmpty()) {
324	            return householdMembers;
325	        }
326	        String householdId = householdMembers.stream()
327	            .map(Owner::getHouseholdId)
328	            .filter(Objects::nonNull)
329	            .findFirst()
330	            .orElseGet(() -> deriveHouseholdId(lastName, address));
331	        owner.setHouseholdId(householdId);
332	        for (Owner member : householdMembers) {
333	            if (!householdId.equals(member.getHouseholdId())) {
334	                member.setHouseholdId(householdId);
335	                ownerRepository.save(member);
336	            }
337	        }
338	        return householdMembers;
339	    }
340	
341	    /**
342	     * Derive a stable, shared household identifier from the normalized last name and address, so
343	     * every owner in the same household deterministically maps to the same value.
344	     */
345	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
346	        String key = normalizedLastName + "\n" + normalizedAddress;
347	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
348	    }
349	
350	    /**
351	     * Reject the create when the owner's derived {@code identityKey} exactly matches that of an
352	     * existing owner. The key —
353	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} — is the single value
354	     * into which the former separate telephone, e-mail and household duplicate checks are
355	     * consolidated: only an exact whole-key match is a duplicate, so two members of the same
356	     * household with different telephones (hence different keys) are both allowed. Evaluated after
357	     * the household has been reconciled (so the {@code householdId} segment is settled) and before
358	     * the owner is persisted, so it reflects the owners present at creation time.
359	     */
360	    private void rejectWhenDuplicateIdentity(Owner owner) {
361	        String identityKey = IdentityKeyNormalizer.derive(owner);
362	        boolean duplicate = ownerRepository.findAll().stream()
363	            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
364	        if (duplicate) {
365	            throw new DuplicateIdentityException(
366	                "an owner with identity key " + identityKey + " already exists");
367	        }
368	    }
