387	    /**
388	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
389	     * before the owner is persisted, so it reflects the owners present at creation time.
390	     */
391	    private long countOwnersRegisteredOn(LocalDate day) {
392	        return ownerRepository.findAll().stream()
393	            .filter(existing -> day.equals(existing.getRegistrationDate()))
394	            .count();
395	    }
396	
397	    /** Maximum number of owners allowed to live in any single city. */
398	    private static final long CITY_CAPACITY = 50L;
399	
400	    /**
401	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
402	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
403	     * is persisted, so it reflects the owners present at creation time.
404	     */
405	    private void rejectWhenCityAtCapacity(Owner owner) {
406	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
407	            throw new CityCapacityExceededException(
408	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
409	        }
410	    }
411	
412	    /**
413	     * Count the existing owners that already live in this owner's city, compared
414	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
415	     * owner is persisted, so it reflects the owners present at creation time.
416	     */
417	    private long countOwnersInCity(Owner owner) {
418	        String city = IdentityNormalizer.normalize(owner.getCity());
419	        return ownerRepository.findAll().stream()
420	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
421	            .count();
422	    }
