424	    /**
425	     * Builds the customer code {@code '<CITY3>-<LAST3>-<NNNN>'}: the upper-cased first
426	     * three letters of the owner's {@code city}, a hyphen, the upper-cased first three
427	     * letters of {@code lastName}, a hyphen, and a 4-digit zero-padded per-city sequence
428	     * equal to one more than the number of owners already in that city (compared
429	     * case-insensitively with collapsed whitespace).
430	     */
431	    private String nextCustomerCode(Owner owner) {
432	        String city3 = prefix3(owner.getCity());
433	        String last3 = prefix3(owner.getLastName());
434	        long sequence = countOwnersInCity(owner) + 1L;
435	        return String.format("%s-%s-%04d", city3, last3, sequence);
436	    }
