438	    /**
439	     * Returns the upper-cased first three letters of {@code value}, or fewer when the value
440	     * is shorter; a {@code null} value yields an empty string.
441	     */
442	    private static String prefix3(String value) {
443	        String name = value == null ? "" : value;
444	        return name.substring(0, Math.min(3, name.length())).toUpperCase();
445	    }
