17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	/**
23	 * Utility for normalizing the postal address submitted when creating an owner. The value is
24	 * trimmed, internal whitespace runs are collapsed to a single space, the result is upper-cased,
25	 * and common abbreviations are expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD},
26	 * {@code AVE -> AVENUE}). The normalized value is what gets stored and returned, and it is also
27	 * the form used for every address comparison (household-duplicate detection and the shared
28	 * household id).
29	 *
30	 * <p>Because the address is a required field, {@link #normalize(String)} rejects a value that is
31	 * blank once normalized by raising an {@link InvalidAddressException} so the request is rejected
32	 * with {@code 400 Bad Request}. {@link #canonical(String)} exposes the same transformation without
33	 * the required-field check, for comparing addresses that may already be stored in another form.
34	 */
35	public final class AddressNormalizer {
36	
37	    /**
38	     * Common street-type abbreviations expanded to their full form. Keys are upper-cased so the
39	     * lookup happens after the value has itself been upper-cased.
40	     */
41	    private static final Map<String, String> ABBREVIATIONS = Map.of(
42	        "ST", "STREET",
43	        "RD", "ROAD",
44	        "AVE", "AVENUE");
45	
46	    private AddressNormalizer() {
47	    }
48	
49	    /**
50	     * Normalize the supplied address for storage.
51	     *
52	     * @param address the raw address value (may be {@code null})
53	     * @return the trimmed, whitespace-collapsed, upper-cased address with common abbreviations expanded
54	     * @throws InvalidAddressException if the value is blank once normalized
55	     */
56	    public static String normalize(String address) {
57	        String canonical = canonical(address);
58	        if (canonical.isEmpty()) {
59	            throw new InvalidAddressException("address must not be blank");
60	        }
61	        return canonical;
62	    }
63	
64	    /**
65	     * Produce the canonical form of the supplied address for equality comparison, applying the same
66	     * transformation as {@link #normalize(String)} but returning an empty string (rather than
67	     * throwing) when the value is {@code null} or blank once normalized.
68	     *
69	     * @param address the raw address value (may be {@code null})
70	     * @return the normalized address, or an empty string when {@code null} or blank
71	     */
72	    public static String canonical(String address) {
73	        if (address == null) {
74	            return "";
75	        }
76	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
77	        if (collapsed.isEmpty()) {
78	            return "";
79	        }
80	        String[] tokens = collapsed.split(" ");
81	        StringBuilder result = new StringBuilder(collapsed.length());
82	        for (int i = 0; i < tokens.length; i++) {
83	            if (i > 0) {
84	                result.append(' ');
85	            }
86	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
87	        }
88	        return result.toString();
89	    }
90	}
