17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Map;
20	
21	/**
22	 * Validates the optional postcode submitted when creating an owner. The postcode is validated
23	 * only <em>when present</em>: a {@code null} postcode is left untouched (an owner created without
24	 * a postcode stays valid). When present it must be a 4-digit value and, when the owner's city
25	 * maps to a known region, must fall within that region's fixed inclusive range
26	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
27	 * region accepts any 4-digit postcode.
28	 *
29	 * <p>An invalid postcode raises an {@link InvalidPostcodeException} so the request is rejected
30	 * with {@code 400 Bad Request}.
31	 */
32	public final class PostcodeValidator {
33	
34	    /** Fixed city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). */
35	    private static final Map<String, String> CITY_REGION = Map.of(
36	        "Sydney", "NSW",
37	        "Melbourne", "VIC",
38	        "Brisbane", "QLD");
39	
40	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
41	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
42	        "NSW", new int[] {2000, 2099},
43	        "VIC", new int[] {3000, 3099},
44	        "QLD", new int[] {4000, 4099});
45	
46	    private PostcodeValidator() {
47	    }
48	
49	    /**
50	     * Validate the supplied postcode for the given city.
51	     *
52	     * @param postcode the raw postcode value (may be {@code null} when absent)
53	     * @param city the owner's city, used to derive the region whose range applies
54	     * @throws InvalidPostcodeException if the postcode is present but not a 4-digit value, or is
55	     *                                  out of range for the city's region
56	     */
57	    public static void validate(String postcode, String city) {
58	        if (postcode == null) {
59	            return;
60	        }
61	        if (!postcode.matches("\\d{4}")) {
62	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
63	        }
64	        String region = city == null ? null : CITY_REGION.get(city);
65	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
66	        if (range != null) {
67	            int value = Integer.parseInt(postcode);
68	            if (value < range[0] || value > range[1]) {
69	                throw new InvalidPostcodeException(
70	                    "postcode " + postcode + " is not valid for region " + region);
71	            }
72	        }
73	    }
74	}
