17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	
21	/**
22	 * Utility for deriving an owner's {@code identityKey}, the single value into which all
23	 * duplicate detection is consolidated. The key is
24	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}: the owner's
25	 * telephone in {@link TelephoneNormalizer E.164} form, the (already lower-cased) e-mail
26	 * address or an empty string when absent, and the shared household identifier or an empty
27	 * string when the owner does not belong to a household.
28	 *
29	 * <p>Because the telephone is part of the key, two members of the same household (the same
30	 * {@code householdId}) with different telephones have different identity keys; only an exact
31	 * whole-key match between a new owner and an existing one is a duplicate.
32	 */
33	public final class IdentityKeyNormalizer {
34	
35	    private IdentityKeyNormalizer() {
36	    }
37	
38	    /**
39	     * Derive the owner's identity key.
40	     *
41	     * @param owner the owner (may be {@code null})
42	     * @return the derived identity key, or {@code null} when the owner is {@code null}
43	     */
44	    public static String derive(Owner owner) {
45	        if (owner == null) {
46	            return null;
47	        }
48	        String telephone = TelephoneNormalizer.toE164(owner.getTelephone());
49	        if (telephone == null) {
50	            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
51	        }
52	        String email = owner.getEmail() == null ? "" : owner.getEmail();
53	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
54	        return telephone + "|" + email + "|" + householdId;
55	    }
56	}
