286	        HttpStatus status = HttpStatus.BAD_REQUEST;
287	        BindingErrorsResponse errors = new BindingErrorsResponse();
288	        BindingResult bindingResult = e.getBindingResult();
289	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
290	        if (bindingResult.hasErrors()) {
291	            errors.addAllErrors(bindingResult);
292	            List<String> errorFields = bindingResult.getFieldErrors().stream()
293	                .map(fieldError -> fieldError.getField())
294	                .distinct()
295	                .toList();
296	            detail.setProperty("errors", errorFields);
297	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
298	                .map(fieldError -> {
299	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
300	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
301	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
302	                        fieldError.getField(),
303	                        defaultMessage,
304	                        rejectedValue);
305	                    return new ValidationMessageDto(message)
306	                        .putAdditionalProperty("field", fieldError.getField())
307	                        .putAdditionalProperty("rejectedValue", rejectedValue)
308	                        .putAdditionalProperty("defaultMessage", defaultMessage);
309	                })
310	                .toList();
311	            logger.debug("Validation error at {} {}: {}",
312	                request.getMethod(),
313	                request.getRequestURI(),
314	                bindingResult.getFieldErrors());
315	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
316	            return ResponseEntity.status(status).body(detail);
317	        }
318	        return ResponseEntity.status(status).body(detail);
319	    }
