20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    Owner toOwner(OwnerDto ownerDto);
34	
35	    /**
36	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
37	     */
38	    default String displayName(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
43	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
44	        return lastName + ", " + firstName;
45	    }
46	
47	    /**
48	     * Returns the upper-cased first letters of firstName and lastName,
49	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
50	     */
51	    default String initials(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        StringBuilder sb = new StringBuilder();
56	        String firstName = owner.getFirstName();
57	        String lastName = owner.getLastName();
58	        if (firstName != null && !firstName.isEmpty()) {
59	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
60	        }
61	        if (lastName != null && !lastName.isEmpty()) {
62	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
63	        }
64	        return sb.toString();
65	    }
66	
67	    /**
68	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
69	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
70	     * Returns {@code null} unless both the customer code and registration date are present.
71	     */
72	    default String membershipNumber(Owner owner) {
73	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
77	        return owner.getCustomerCode() + "-M" + yy;
78	    }
79	
80	    /**
81	     * Returns the owner's numeric membership level. Starts at {@code 1}; adds {@code 1} when an
82	     * email address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is
83	     * 0); capped at {@code 3} (level 4 is reserved for tenure).
84	     */
85	    default Integer membershipLevel(Owner owner) {
86	        if (owner == null) {
87	            return null;
88	        }
89	        int level = 1;
90	        String email = owner.getEmail();
91	        if (email != null && !email.isEmpty()) {
92	            level++;
93	        }
94	        Integer namesakeCount = owner.getNamesakeCount();
95	        if (namesakeCount != null && namesakeCount == 0) {
96	            level++;
97	        }
98	        return Math.min(level, 3);
99	    }
100	
101	    /** Fixed city-to-region table used to derive an owner's locality. */
102	    Map<String, String> CITY_REGION = Map.of(
103	        "Sydney", "NSW",
104	        "Melbourne", "VIC",
105	        "Brisbane", "QLD");
106	
107	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
108	    Map<String, int[]> REGION_POSTCODES = Map.of(
109	        "NSW", new int[] {2000, 2099},
110	        "VIC", new int[] {3000, 3099},
111	        "QLD", new int[] {4000, 4099});
112	
113	    /**
114	     * Derives the owner's locality (region), preferring the postcode. The postcode range is
115	     * consulted first ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); only
116	     * when the postcode is absent or falls in no known range does it fall back to the fixed
117	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
118	     * Returns {@code "UNKNOWN"} when neither the postcode nor the city yields a region.
119	     */
120	    default String locality(Owner owner) {
121	        if (owner == null) {
122	            return null;
123	        }
124	        String byPostcode = regionForPostcode(owner.getPostcode());
125	        if (byPostcode != null) {
126	            return byPostcode;
127	        }
128	        String city = owner.getCity();
129	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
130	    }
131	
132	    /**
133	     * Returns the region whose inclusive postcode range contains {@code postcode}, or {@code null}
134	     * when the postcode is absent, not a 4-digit value, or in no known range.
135	     */
136	    private String regionForPostcode(String postcode) {
137	        if (postcode == null || !postcode.matches("\\d{4}")) {
138	            return null;
139	        }
140	        int value = Integer.parseInt(postcode);
141	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
142	            int[] range = entry.getValue();
143	            if (value >= range[0] && value <= range[1]) {
144	                return entry.getKey();
145	            }
146	        }
147	        return null;
148	    }
149	
150	    /**
151	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
152	     * on its registration day at creation time). A {@code null} stored value is treated as
153	     * {@code false}, so the field is always present in the response.
154	     */
155	    default Boolean bulkSignupWarning(Owner owner) {
156	        if (owner == null) {
157	            return null;
158	        }
159	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
160	    }
161	
162	    /**
163	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
164	     * present, otherwise {@code PHONE}.
165	     */
166	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        String email = owner.getEmail();
171	        return (email != null && !email.isEmpty())
172	            ? OwnerDto.ContactPreferenceEnum.EMAIL
173	            : OwnerDto.ContactPreferenceEnum.PHONE;
174	    }
175	
176	    /**
177	     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
178	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
179	     */
180	    default String identityKey(Owner owner) {
181	        return IdentityKeyNormalizer.derive(owner);
182	    }
183	
184	    @Mapping(target = "id", ignore = true)
185	    @Mapping(target = "pets", ignore = true)
186	    Owner toOwner(OwnerFieldsDto ownerDto);
187	
188	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
189	
190	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
191	
192	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
193	        OwnerPageDto ownerPageDto = new OwnerPageDto();
194	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
195	        ownerPageDto.setPage(ownerPage.getNumber());
196	        ownerPageDto.setSize(ownerPage.getSize());
197	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
198	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
199	        return ownerPageDto;
200	    }
201	}
